<script setup>
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import api from '../api'
const sidebarOpen=ref(false),newMessage=ref(''),selectedConvo=ref(0),conversations=ref([]),messages=ref([]),currentUser=ref(JSON.parse(localStorage.getItem('user')||'{}'))
const activeConvo=computed(()=>conversations.value.find(c=>c.id===selectedConvo.value)||null)
const selectConvo=async(convo)=>{selectedConvo.value=convo.id;try{messages.value=(await api.get(`/messages/${convo.sender_id===currentUser.value.id?convo.receiver_id:convo.sender_id}`)).data}catch{messages.value=[]}}
const loadConversations=async()=>{try{conversations.value=(await api.get('/messages/conversations')).data;if(conversations.value.length)selectConvo(conversations.value[0])}catch{conversations.value=[]}}
const sendMessage=async()=>{if(!newMessage.value.trim()||!activeConvo.value)return;const receiverId=activeConvo.value.sender_id===currentUser.value.id?activeConvo.value.receiver_id:activeConvo.value.sender_id;try{await api.post('/messages',{receiver_id:receiverId,item_id:activeConvo.value.item_id,message:newMessage.value});messages.value.push({text:newMessage.value,time:'Just now',sent:true});newMessage.value=''}catch{}}
onMounted(loadConversations)
</script>
<template><div class="msg-wrapper"><div v-if="sidebarOpen" class="overlay" @click="sidebarOpen=false"></div><div class="sidebar" :class="{open:sidebarOpen}"><div class="sidebar-top"><div class="sidebar-brand"><div class="sidebar-logo">⌂</div><div><p class="sidebar-title">LDCU iFound</p><p class="sidebar-sub">Lost &amp; Found System</p></div></div><button class="close-btn" @click="sidebarOpen=false">✕</button></div><nav class="sidebar-nav"><RouterLink to="/dashboard" class="nav-item">Dashboard</RouterLink><RouterLink to="/lost-and-found" class="nav-item">Lost &amp; Found</RouterLink><RouterLink to="/claims" class="nav-item">Claims Management</RouterLink><RouterLink to="/history" class="nav-item">Claimed History</RouterLink><RouterLink to="/messages" class="nav-item active">Messages</RouterLink><RouterLink to="/post-item" class="nav-item">Post Item</RouterLink><RouterLink to="/profile" class="nav-item">My Profile</RouterLink></nav><div class="sidebar-footer">© 2025 LDCU iFound System</div></div><div class="main"><div class="topbar"><button class="menu-btn" @click="sidebarOpen=!sidebarOpen">☰</button><div class="topbar-brand"><div class="topbar-logo">⌂</div><div><p class="topbar-name">LDCU iFound</p><p class="topbar-sub">Lost &amp; Found System</p></div></div></div><div class="messages-layout"><div class="convo-list"><div class="convo-header"><h3>Messages</h3><p>Chat with claimants and reporters</p></div><div v-for="conversation in conversations" :key="conversation.id" class="convo-item" :class="{active:selectedConvo===conversation.id}" @click="selectConvo(conversation)"><div class="avatar">{{conversation.initials}}</div><div class="convo-info"><div class="convo-top"><span class="convo-name">{{conversation.name}}</span><span class="convo-time">{{conversation.time}}</span></div><p class="convo-subject">{{conversation.subject}}</p><p class="convo-preview">{{conversation.preview}}</p></div><div v-if="conversation.unread" class="unread-dot"></div></div></div><div class="chat-area" v-if="activeConvo"><div class="chat-header"><div class="avatar small">{{activeConvo.initials}}</div><div><p class="chat-name">{{activeConvo.name}}</p><p class="chat-subject">{{activeConvo.subject}}</p></div></div><div class="chat-messages"><div v-for="(message,index) in messages" :key="message.id||index" class="msg-row" :class="message.sent?'sent':'received'"><div class="msg-bubble" :class="message.sent?'sent-bubble':'received-bubble'">{{message.text||message.message}}</div><p class="msg-time">{{message.time}}</p><div v-if="message.approved" class="approved-notice">Claim for this item has been Approved ✓</div></div></div><div class="chat-input"><input v-model="newMessage" placeholder="Type a message..." @keyup.enter="sendMessage"/><button class="send-btn" @click="sendMessage">➤</button></div></div></div></div></div></template>
<style scoped>
*{margin:0;padding:0;box-sizing:border-box}.msg-wrapper{display:flex;min-height:100vh;font-family:'Segoe UI',sans-serif;background:#f5f6fa}.overlay{position:fixed;inset:0;background:rgba(0,0,0,.4);z-index:99}.sidebar{position:fixed;top:0;left:-320px;width:280px;height:100vh;background:#0d1b2e;display:flex;flex-direction:column;padding:24px 0;z-index:100;transition:left .3s}.sidebar.open{left:0}.sidebar-top{display:flex;justify-content:space-between;padding:0 20px 24px;border-bottom:1px solid rgba(255,255,255,.1)}.sidebar-brand,.topbar-brand{display:flex;align-items:center;gap:12px}.sidebar-logo,.topbar-logo{width:42px;height:42px;background:#1a3c8f;border-radius:10px;color:#fff;display:flex;align-items:center;justify-content:center}.topbar-logo{width:38px;height:38px}.sidebar-title{color:#fff;font-weight:700}.sidebar-sub{color:rgba(255,255,255,.5);font-size:.75rem}.close-btn,.menu-btn{background:none;border:0;cursor:pointer}.close-btn{color:#fff}.sidebar-nav{display:flex;flex-direction:column;gap:4px;padding:16px 12px;flex:1}.nav-item{padding:12px 16px;color:rgba(255,255,255,.65);text-decoration:none;border-radius:10px}.nav-item.active,.nav-item:hover{background:#1a3c8f;color:#fff}.sidebar-footer{color:rgba(255,255,255,.35);padding:16px;text-align:center;font-size:.75rem}.main{flex:1;display:flex;flex-direction:column;overflow:hidden}.topbar{background:#fff;padding:12px 24px;display:flex;gap:16px;align-items:center;border-bottom:1px solid #e8eaed}.topbar-name{font-weight:700}.topbar-sub{font-size:.72rem;color:#888}.messages-layout{display:grid;grid-template-columns:320px 1fr;flex:1;height:calc(100vh - 62px)}.convo-list{border-right:1px solid #e8eaed;background:#fff;overflow-y:auto}.convo-header{padding:20px;border-bottom:1px solid #e8eaed}.convo-header h3{color:#111}.convo-header p,.convo-time{font-size:.8rem;color:#888}.convo-item{display:flex;gap:12px;padding:14px 20px;cursor:pointer;border-bottom:1px solid #f5f5f5}.convo-item.active{background:#f0f4ff}.avatar{width:44px;height:44px;border-radius:50%;background:#344563;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;flex-shrink:0}.avatar.small{width:36px;height:36px;background:#1a3c8f}.convo-info{flex:1;min-width:0}.convo-top{display:flex;justify-content:space-between}.convo-name,.chat-name{font-weight:700;color:#111}.convo-subject{font-size:.8rem;color:#555}.convo-preview{font-size:.78rem;color:#888;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.unread-dot{width:8px;height:8px;background:#ef4444;border-radius:50%;margin-top:6px}.chat-area{display:flex;flex-direction:column;background:#f5f6fa}.chat-header{display:flex;gap:12px;padding:16px 24px;background:#fff;border-bottom:1px solid #e8eaed}.chat-subject{font-size:.8rem;color:#888}.chat-messages{flex:1;overflow-y:auto;padding:24px;display:flex;flex-direction:column;gap:16px}.msg-row{display:flex;flex-direction:column}.msg-row.sent{align-items:flex-end}.msg-row.received{align-items:flex-start}.msg-bubble{max-width:65%;padding:12px 16px;border-radius:16px}.sent-bubble{background:#1a3c8f;color:#fff}.received-bubble{background:#fff;color:#333}.msg-time{font-size:.75rem;color:#aaa;margin-top:4px}.approved-notice{color:#16a34a;background:#dcfce7;padding:8px 16px;border-radius:20px}.chat-input{display:flex;gap:10px;padding:16px 24px;background:#fff}.chat-input input{flex:1;padding:12px 16px;border:1.5px solid #dde1e9;border-radius:24px}.send-btn{width:44px;height:44px;border:0;border-radius:50%;background:#1a3c8f;color:#fff;cursor:pointer}
</style>